#!/usr/bin/env node
// Applies every migration under ./drizzle (generated by `npm run db:generate`)
// to the database at DATABASE_URL, in order, tracking what's already been
// applied — this is the Postgres/Supabase replacement for the SQLite
// client's "apply schema.sql idempotently at boot" pattern. Deliberately
// a one-time, explicit operator step instead: the exact bug that pattern
// caused (a widened CHECK constraint silently never applying to an
// existing SQLite table) is precisely what an ordered, tracked migration
// history prevents.
import { Pool } from "pg";
import { drizzle } from "drizzle-orm/node-postgres";
import { migrate } from "drizzle-orm/node-postgres/migrator";
import { supabasePoolSsl } from "../src/server/db/postgres/ssl.mjs";

const connectionString = process.env.DATABASE_URL;
if (!connectionString) {
  console.error("DATABASE_URL is not set. Copy .env.example to .env and fill it in first.");
  process.exit(1);
}

// Supabase's pooler chain is rooted at Supabase's own self-issued CA, not a
// publicly trusted one — see src/server/db/postgres/ssl.mjs for why `ca`
// has to be supplied explicitly, not just `rejectUnauthorized: true`.
const pool = new Pool({ connectionString, max: 1, ssl: supabasePoolSsl });
const db = drizzle(pool);

console.log("Applying migrations from ./drizzle ...");
await migrate(db, { migrationsFolder: "./drizzle" });
console.log("Done.");

await pool.end();
